// convention and is spelled that way in every member's declaration, so renaming it
// is a fleet migration, not a tidy-up. The list is exhaustive and closed — a new
// pack never joins it.
const PACK_MJS = /^packs\/([^/]+)\/pack\.mjs$/;
const KEBAB = /^[a-z0-9]+(-[a-z0-9]+)*$/;
const GRANDFATHERED = new Set(['grow_with_claudinite']);

