  id: 'pack-name-kebab-case',
  severity: 'blocking',
  description: "A canon pack's directory name is kebab-case — lowercase words joined by single hyphens",
  doc: 'packs/README.md',
  why: "the directory name is the pack's public id — members declare it, migrations seed it and the whole corpus spells it, so a name in another casing is renamed later across every one of those places",

  run(ctx) {
    return ctx.files.flatMap((file) => {
      const m = PACK_MJS.exec(file);
      if (!m) return [];
      const name = m[1];
